// test/goldens/app-badge.golden.test.ts
// PIXEL GOLDEN: the unread badge, drawn once at its only size.
// fixed-size: the badge is always 64x64 points; it never lays out to its container.
import { Skia } from '@shopify/react-native-skia';

import { paintBadgePng } from '@/ui/badge/paint-badge-png';
import { toMatchPixelGolden } from '@test/goldens/skia-golden';

expect.extend({ toMatchImageSnapshot: toMatchPixelGolden });

const SIZE = 64;

describe('app badge golden', () => {
  it('draws the badge with three unread tasks', () => {
    const png = paintBadgePng(Skia, { count: 3, width: SIZE, height: SIZE, elapsedMs: 0 });
    expect(Buffer.from(png)).toMatchImageSnapshot({ customSnapshotIdentifier: 'app-badge' });
  });
});

// test/goldens/pipeline.golden.test.ts
// PIXEL GOLDEN: proves the golden project draws real pixels with CanvasKit, through a drawing
// defined here (not a production surface), at one size.
import { Skia } from '@shopify/react-native-skia';

import { toMatchPixelGolden } from '@test/goldens/skia-golden';

import type { SkCanvas } from '@shopify/react-native-skia';

expect.extend({ toMatchImageSnapshot: toMatchPixelGolden });

function drawDot(canvas: SkCanvas): void {
  const paint = Skia.Paint();
  canvas.drawCircle(16, 16, 8, paint);
}

describe('pipeline golden', () => {
  it('draws one dot', () => {
    const png = renderOffscreen(Skia, { draw: drawDot, width: 32, height: 32, elapsedMs: 0 });
    expect(Buffer.from(png)).toMatchImageSnapshot({ customSnapshotIdentifier: 'pipeline-dot' });
  });
});
